import { Task, TaskStatus } from '../domain/Task';
import { TaskRepository } from '../domain/TaskRepository';

export interface ListTasksFilter {
  status?: TaskStatus;
  assigneeId?: string;
}

export class ListTasksUseCase {
  constructor(private taskRepository: TaskRepository) {}

  execute(projectId: string, filter?: ListTasksFilter): Task[] {
    let tasks: Task[];

    if (filter?.status && filter?.assigneeId) {
      tasks = this.taskRepository.getByProjectIdAndStatus(projectId, filter.status);
      tasks = tasks.filter((t) => t.assigneeId === filter.assigneeId);
    } else if (filter?.status) {
      tasks = this.taskRepository.getByProjectIdAndStatus(projectId, filter.status);
    } else if (filter?.assigneeId) {
      tasks = this.taskRepository.getByProjectIdAndAssignee(projectId, filter.assigneeId);
    } else {
      tasks = this.taskRepository.getByProjectId(projectId);
    }

    return tasks;
  }
}

=====SOURCE-END=====

